import tensorflow as tf

def order_fake_devices():
    # Assume we have a list of fake devices generated by some mechanism
    fake_devices = [
        (tf.config.physical_device_spec()('GPU', 0), 0),
        (tf.config.physical_device_spec()('GPU', 1), 2),
        (tf.config.physical_device_spec()('GPU', 0), 1),
        (tf.config.physical_device_spec()('GPU', 1), 0),
    ]

    # Sort by ordinal number, with primary tie-breaking by physical device ID
    sorted_devices = sorted(fake_devices, key=lambda x: (x[1], x[0]))

    return sorted_devices

if __name__ == "__main__":
    ordered_devices = order_fake_devices()
    for device, ordinal in ordered_devices:
        print(f"Device: {device}, Ordinal: {ordinal}")
